pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;

    function setUp() public {
        c = new LiquidityPool(0, bytes16(0), address(this), address(new __InvMutHandleStub()), address(new __InvMutHandleStub()));
        // The deployed share stub is the adversarial counterparty: c's transferFrom low-level
        // calls into it and must propagate its returned bool. Configure it to return FALSE
        // (a failing/conflicting transfer outcome) so the difference is observable.
        __InvMutHandleStub(payable(address(c.share()))).setTransferFromResult(false);
    }

    function testFuzz_property(address from, address to, uint256 amount) public {
        vm.assume(amount < type(uint256).max);

        bool returned = c.transferFrom(from, to, amount);

        // General rule: for ANY caller and ANY arguments, c.transferFrom returns exactly
        // the boolean its share token returned. Here the share token always returns false,
        // so c.transferFrom must return false for every input.
        assertTrue(returned == false, "transferFrom must propagate the share token's false result");
    }
}

